import 'package:flutter/material.dart';
import '../../core/auth_controller.dart';
import '../../core/models.dart';
import '../../core/theme.dart';
class ProfileScreen extends StatelessWidget{final AppUser? user;const ProfileScreen({super.key,required this.user});@override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:const Text('Perfil')),body:ListView(padding:const EdgeInsets.all(18),children:[GlassCard(child:Row(children:[CircleAvatar(radius:28,child:Text(user?.email.isNotEmpty==true?user!.email[0].toUpperCase():'N')),const SizedBox(width:14),Expanded(child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text(user?.email.split('@').first??'Cuenta',style:const TextStyle(fontSize:18,fontWeight:FontWeight.w800)),Text(user?.email??'',style:const TextStyle(color:AppColors.muted))]))])),const SizedBox(height:16),GlassCard(child:Column(children:[ListTile(leading:const Icon(Icons.workspace_premium_outlined,color:AppColors.cyan),title:const Text('Plan'),trailing:Text(user?.tier??'FREE')),ListTile(leading:const Icon(Icons.bolt,color:AppColors.yellow),title:const Text('Créditos'),trailing:Text('${user?.balance??0}')),ListTile(leading:const Icon(Icons.shield_outlined,color:AppColors.cyan),title:const Text('Rol'),trailing:Text(user?.role??'USER'))])),const SizedBox(height:16),FilledButton.icon(onPressed:()=>Navigator.pop(context),icon:const Icon(Icons.arrow_back),label:const Text('Volver'))]));}
